package com.liam.mixology;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * In-world lab guidance: lever outlines with remaining pull counts for
 * the next mix, the target station, the quick-action flash, and the
 * ready vessel.
 */
@Singleton
public class MixologyLabOverlay extends Overlay
{
	private static final Color MOX = new Color(90, 130, 255);
	private static final Color AGA = new Color(60, 200, 80);
	private static final Color LYE = new Color(235, 70, 70);
	private static final Color STATION = new Color(255, 0, 255);
	private static final Color QUICK = new Color(0, 255, 60);
	private static final Color VESSEL = new Color(255, 255, 255);
	private static final Color DIGWEED = new Color(255, 220, 60);

	private final Client client;
	private final MixologyState state;
	private final MixologyConfig config;
	private final MixologyObjects objects;
	private final ModelOutlineRenderer outliner;

	@Inject
	private MixologyLabOverlay(Client client, MixologyState state, MixologyConfig config,
		MixologyObjects objects, ModelOutlineRenderer outliner)
	{
		this.client = client;
		this.state = state;
		this.config = config;
		this.objects = objects;
		this.outliner = outliner;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!state.isInLab())
		{
			return null;
		}

		// pickable digweed despawns in ~20s, so it draws alongside
		// whatever else is on screen, never queued behind it
		if (config.highlightDigweedSpawn())
		{
			for (int herbId : state.getReadyHerbObjectIds())
			{
				TileObject herb = objects.get(herbId);
				if (herb != null)
				{
					outliner.drawOutline(herb, 4, DIGWEED, 2);
					drawLabel(graphics, herb, "Digweed!", DIGWEED);
				}
			}
		}

		// the quick-action window is a two-tick reflex cue: while open it
		// IS the action, overriding whatever the queue was showing
		if (config.guideQuickAction() && state.getQuickActionId() != 0)
		{
			TileObject station = objects.get(state.getQuickActionId());
			if (station != null)
			{
				outliner.drawOutline(station, 5, QUICK, 2);
				drawLabel(graphics, station, "CLICK!", QUICK);
				return null;
			}
		}

		// otherwise exactly ONE action on screen, in gameplay order
		switch (state.getLabAction())
		{
			case COLLECT_VESSEL:
			{
				TileObject vessel = objects.get(MixologyObjects.VESSEL);
				if (vessel != null)
				{
					outliner.drawOutline(vessel, 3, VESSEL, 2);
					drawLabel(graphics, vessel, "Collect", VESSEL);
				}
				break;
			}
			case MIX:
			{
				if (config.guideLevers())
				{
					int[] remaining = state.getLeverRemaining();
					drawLever(graphics, MixologyObjects.LEVER_MOX, remaining[0], MOX);
					drawLever(graphics, MixologyObjects.LEVER_AGA, remaining[1], AGA);
					drawLever(graphics, MixologyObjects.LEVER_LYE, remaining[2], LYE);
				}
				break;
			}
			case USE_STATION:
			{
				if (config.guideStations())
				{
					TileObject station = objects.get(state.getActionStationId());
					if (station != null)
					{
						outliner.drawOutline(station, 3, STATION, 2);
						drawLabel(graphics, station, "Insert", STATION);
					}
				}
				break;
			}
			case ATTEND_STATION:
			{
				if (config.guideStations())
				{
					TileObject station = objects.get(state.getActionStationId());
					if (station != null)
					{
						outliner.drawOutline(station, 2, STATION, 2);
					}
				}
				break;
			}
			case DEPOSIT:
			{
				TileObject conveyor = objects.get(MixologyObjects.CONVEYOR);
				if (conveyor != null)
				{
					outliner.drawOutline(conveyor, 3, QUICK, 2);
					drawLabel(graphics, conveyor, "Deposit", QUICK);
				}
				break;
			}
			default:
		}
		return null;
	}

	private void drawLever(Graphics2D graphics, int objectId, int remaining, Color color)
	{
		if (remaining <= 0)
		{
			return;
		}
		TileObject lever = objects.get(objectId);
		if (lever == null)
		{
			return;
		}
		outliner.drawOutline(lever, 3, color, 2);
		drawLabel(graphics, lever, "×" + remaining, color);
	}

	private void drawLabel(Graphics2D graphics, TileObject object, String text, Color color)
	{
		Point location = Perspective.getCanvasTextLocation(
			client, graphics, object.getLocalLocation(), text, 120);
		if (location == null)
		{
			return;
		}
		float size = 16f * config.overlayScale() / 100f;
		graphics.setFont(graphics.getFont().deriveFont(Font.BOLD, size));
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, location.getX() + 1, location.getY() + 1);
		graphics.setColor(color);
		graphics.drawString(text, location.getX(), location.getY());
	}
}

package com.liam.mixology;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * The ten Mastering Mixology potions, declared in ORDER VARBIT VALUE order
 * (varbit value = ordinal + 1). WARNING: this order does NOT match item-id
 * order for AAM/AAL and LLM/LLA. Points are the post-rebalance ordered
 * hand-in rewards (mox/aga/lye), verified against the wiki.
 */
@Getter
@RequiredArgsConstructor
public enum MixPotion
{
	MMM("Mammoth-might mix", "MMM", 20, 0, 0, 30011, 30021),
	MMA("Mystic mana amalgam", "MMA", 20, 10, 0, 30012, 30022),
	MML("Marley's moonlight", "MML", 20, 0, 10, 30013, 30023),
	AAA("Alco-augmentator", "AAA", 0, 20, 0, 30014, 30024),
	AAM("Azure aura mix", "AAM", 10, 20, 0, 30016, 30026),
	AAL("Aqualux amalgam", "AAL", 0, 20, 10, 30015, 30025),
	LLL("Liplack liquor", "LLL", 0, 0, 20, 30017, 30027),
	LLM("Megalite liquid", "LLM", 10, 0, 20, 30019, 30029),
	LLA("Anti-leech lotion", "LLA", 0, 10, 20, 30018, 30028),
	MAL("Mixalot", "MAL", 20, 20, 20, 30020, 30030);

	private final String displayName;
	private final String code;
	private final int moxPoints;
	private final int agaPoints;
	private final int lyePoints;
	private final int unfinishedItemId;
	private final int finishedItemId;

	/**
	 * @param varbitValue the order TYPE varbit value (1-10); 0 = no order
	 */
	public static MixPotion fromVarbit(int varbitValue)
	{
		int idx = varbitValue - 1;
		return idx >= 0 && idx < values().length ? values()[idx] : null;
	}

	public static String modifierName(int modifierVarbitValue)
	{
		switch (modifierVarbitValue)
		{
			case 1:
				return "Agitator";
			case 2:
				return "Retort";
			case 3:
				return "Alembic";
			default:
				return "?";
		}
	}
}

package com.liam.mixology;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Provider;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.DecorativeObjectDespawned;
import net.runelite.api.events.DecorativeObjectSpawned;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GraphicsObjectCreated;
import net.runelite.api.events.GroundObjectDespawned;
import net.runelite.api.events.GroundObjectSpawned;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * Mastering Mixology optimizer: ranks the current orders by how much each
 * potion raises the minimum of the resin-to-cost ratios for the selected
 * shop reward, recommends the digweed target, and tracks goal progress
 * with a session-rate ETA. Reads client-side state only (varbits, varps,
 * the inventory, and the lab's scene objects); nothing is automated.
 */
@Slf4j
@PluginDescriptor(
	name = "Noot's Mixology",
	description = "Order picking, lab step guidance, digweed alerts and reward tracking for Mastering Mixology, tuned to the price of the reward you are saving for",
	tags = {"mixology", "mastering", "herblore", "minigame", "aldarium", "varlamore", "potion", "orders", "digweed", "resin", "helper", "skilling"}
)
public class MixologyPlugin extends Plugin
{
	private static final int[] TYPE_VARBITS = {
		VarbitID.MM_LAB_ORDER_1_TYPE, VarbitID.MM_LAB_ORDER_2_TYPE, VarbitID.MM_LAB_ORDER_3_TYPE,
	};
	private static final int[] MODIFIER_VARBITS = {
		VarbitID.MM_LAB_ORDER_1_MODIFIER, VarbitID.MM_LAB_ORDER_2_MODIFIER, VarbitID.MM_LAB_ORDER_3_MODIFIER,
	};
	// one per herb spot, same corner order as MixologyObjects.HERB_SPOTS
	private static final int[] HERB_VARBITS = {
		VarbitID.MM_HERB_READY_1, VarbitID.MM_HERB_READY_2,
		VarbitID.MM_HERB_READY_3, VarbitID.MM_HERB_READY_4,
	};
	private static final int LAB_REGION = 5521;
	private static final Color FLASH_DIGWEED = new Color(255, 220, 60);
	private static final Color FLASH_ORDERED = new Color(0, 220, 90);

	@Inject
	private Client client;

	@Inject
	private MixologyConfig config;

	@Inject
	private MixologyState state;

	@Inject
	private MixologyOverlay overlay;

	@Inject
	private DigweedFlashOverlay digweedOverlay;

	@Inject
	private MixologyLabOverlay labOverlay;

	@Inject
	private MixologyScreenFlashOverlay screenFlashOverlay;

	@Inject
	private MixologyObjects labObjects;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private Provider<MixologyPanel> panelProvider;

	private MixologyPanel panel;
	private NavigationButton navButton;
	private final int[] lastSignals = new int[9];
	private boolean signalsPrimed;

	private final List<Integer> inventoryItems = new ArrayList<>();
	private final java.util.Set<Integer> warnedItemIds = new java.util.HashSet<>();
	private int flashStationId;
	private int flashStartProgress;
	private int flashStartSkillshot;
	private int flashWindow;
	private boolean warnedMixerValues;
	private boolean warnedHerbSignals;
	private boolean wasHerbReady;
	private boolean wasTargetAttention;
	/**
	 * The held digweed was combined into a potion (it left the inventory
	 * inside the lab), so keep watching for its target order.
	 */
	private boolean digweedArmed;

	private static boolean take(java.util.Map<MixPotion, Integer> counts, MixPotion p)
	{
		Integer have = counts.get(p);
		if (have == null || have <= 0)
		{
			return false;
		}
		counts.put(p, have - 1);
		return true;
	}

	/**
	 * @return the station object id holding this potion (consuming the
	 * entry), or 0.
	 */
	private static int takeStation(List<int[]> stationContents, MixPotion p)
	{
		for (java.util.Iterator<int[]> it = stationContents.iterator(); it.hasNext(); )
		{
			int[] entry = it.next();
			if (entry[1] == p.ordinal())
			{
				it.remove();
				return entry[0];
			}
		}
		return 0;
	}

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(overlay);
		overlayManager.add(digweedOverlay);
		overlayManager.add(labOverlay);
		overlayManager.add(screenFlashOverlay);
		panel = panelProvider.get();
		panel.startAutoRefresh();
		navButton = NavigationButton.builder()
			.tooltip("Noot's Mixology")
			.icon(createIcon())
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		signalsPrimed = false;
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		overlayManager.remove(digweedOverlay);
		overlayManager.remove(labOverlay);
		overlayManager.remove(screenFlashOverlay);
		labObjects.clear();
		if (panel != null)
		{
			panel.stopAutoRefresh();
		}
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		state.setTargetReward(config.targetReward());
		state.setInLab(inLab());

		// Reading at tick boundaries sidesteps the mid-delivery window
		// where all order varbits are momentarily reset to zero.
		int[] signals = new int[9];
		for (int i = 0; i < 3; i++)
		{
			signals[i] = client.getVarbitValue(TYPE_VARBITS[i]);
			signals[3 + i] = client.getVarbitValue(MODIFIER_VARBITS[i]);
		}
		signals[6] = client.getVarpValue(VarPlayerID.MIXOLOGY_MOX_POINTS);
		signals[7] = client.getVarpValue(VarPlayerID.MIXOLOGY_AGA_POINTS);
		signals[8] = client.getVarpValue(VarPlayerID.MIXOLOGY_LYE_POINTS);

		if (!signalsPrimed || !java.util.Arrays.equals(signals, lastSignals))
		{
			System.arraycopy(signals, 0, lastSignals, 0, signals.length);
			signalsPrimed = true;
			recompute(signals);
		}
		computeGuidance();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INV)
		{
			return;
		}
		boolean hadDigweed = inventoryItems.contains(ItemID.MM_LAB_SPECIAL_HERB);
		inventoryItems.clear();
		ItemContainer container = event.getItemContainer();
		if (container != null)
		{
			for (Item item : container.getItems())
			{
				if (item != null && item.getId() > 0)
				{
					inventoryItems.add(item.getId());
				}
			}
		}
		// digweed leaving the inventory inside the lab = combined into a
		// potion (or dropped to unblock spawns); either way keep watching
		// for its target order
		if (hadDigweed && !inventoryItems.contains(ItemID.MM_LAB_SPECIAL_HERB) && inLab())
		{
			digweedArmed = true;
			log.debug("digweed left inventory in the lab, arming target-order watch");
		}
		// react instantly (collect -> next lever guidance, no tick lag)
		computeGuidance();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (MixologyConfig.GROUP.equals(event.getGroup()))
		{
			// reward or mode changes re-rank the same signals
			signalsPrimed = false;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		// mixer slots, station progress/contents, herbs, skillshots, vessel
		switch (event.getVarbitId())
		{
			case VarbitID.MM_LAB_MIXER_SLOT_0:
			case VarbitID.MM_LAB_MIXER_SLOT_1:
			case VarbitID.MM_LAB_MIXER_SLOT_2:
			case VarbitID.MM_RETORT_PROGRESS:
			case VarbitID.MM_ALEMBIC_PROGRESS:
			case VarbitID.MM_AGITATOR_PROGRESS:
			case VarbitID.MM_HERB_READY_1:
			case VarbitID.MM_HERB_READY_2:
			case VarbitID.MM_HERB_READY_3:
			case VarbitID.MM_HERB_READY_4:
			case VarbitID.MM_LAB_HIT_SKILLSHOT_AGITATOR:
			case VarbitID.MM_LAB_HIT_SKILLSHOT_ALEMBIC:
			case VarbitID.MM_LAB_VESSEL_READY:
			case VarbitID.MM_LAB_AGITATOR_POTION:
			case VarbitID.MM_LAB_RETORT_POTION:
			case VarbitID.MM_LAB_ALEMBIC_POTION:
				computeGuidance();
				break;
			default:
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		labObjects.track(event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		labObjects.untrack(event.getGameObject());
	}

	@Subscribe
	public void onDecorativeObjectSpawned(DecorativeObjectSpawned event)
	{
		labObjects.track(event.getDecorativeObject());
	}

	@Subscribe
	public void onDecorativeObjectDespawned(DecorativeObjectDespawned event)
	{
		labObjects.untrack(event.getDecorativeObject());
	}

	@Subscribe
	public void onGroundObjectSpawned(GroundObjectSpawned event)
	{
		labObjects.track(event.getGroundObject());
	}

	@Subscribe
	public void onGroundObjectDespawned(GroundObjectDespawned event)
	{
		labObjects.untrack(event.getGroundObject());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOADING:
			case LOGIN_SCREEN:
			case HOPPING:
				labObjects.clear();
				state.setQuickActionId(0);
				flashStationId = 0;
				break;
			default:
		}
	}

	/**
	 * Quick-action windows announce themselves with a station VFX; the
	 * window is measured in station progress ticks (agitator 2, alembic 1)
	 * and ends early on a hit (skillshot varbit) or a missed window.
	 */
	@Subscribe
	public void onGraphicsObjectCreated(GraphicsObjectCreated event)
	{
		int id = event.getGraphicsObject().getId();
		if (id == SpotanimID.VFX_MACHINERY_ALCHEMY01_AGITATOR01
			&& client.getVarbitValue(VarbitID.MM_LAB_AGITATOR_POTION) != 0)
		{
			flashStationId = MixologyObjects.STATION_AGITATOR;
			flashStartProgress = client.getVarbitValue(VarbitID.MM_AGITATOR_PROGRESS);
			// the hit varbit may still hold a stale value from a previous
			// success; a hit is a CHANGE from this baseline, not non-zero
			flashStartSkillshot = client.getVarbitValue(VarbitID.MM_LAB_HIT_SKILLSHOT_AGITATOR);
			flashWindow = 2;
		}
		else if (id == SpotanimID.VFX_MACHINERY_ALCHEMY01_ALEMBIC01
			&& client.getVarbitValue(VarbitID.MM_LAB_ALEMBIC_POTION) != 0)
		{
			flashStationId = MixologyObjects.STATION_ALEMBIC;
			flashStartProgress = client.getVarbitValue(VarbitID.MM_ALEMBIC_PROGRESS);
			flashStartSkillshot = client.getVarbitValue(VarbitID.MM_LAB_HIT_SKILLSHOT_ALEMBIC);
			flashWindow = 1;
		}
	}

	/**
	 * Lab guidance: what to mix at the levers, which station to use, and
	 * whether a quick-action window is open. Runs every tick (cheap).
	 */
	private void computeGuidance()
	{
		// vessel
		int vesselPotion = client.getVarbitValue(VarbitID.MM_LAB_VESSEL_READY);
		state.setVesselReady(vesselPotion != 0);

		// tally what exists, by form: finished vs unfinished vs in-station
		// vs in-vessel; orders are then covered IN SEQUENCE so duplicate
		// orders of the same potion each claim their own copy.
		java.util.Map<MixPotion, Integer> finished = new java.util.HashMap<>();
		java.util.Map<MixPotion, Integer> unfinished = new java.util.HashMap<>();
		for (int itemId : inventoryItems)
		{
			boolean known = false;
			for (MixPotion p : MixPotion.values())
			{
				if (itemId == p.getFinishedItemId())
				{
					finished.merge(p, 1, Integer::sum);
					known = true;
				}
				else if (itemId == p.getUnfinishedItemId())
				{
					unfinished.merge(p, 1, Integer::sum);
					known = true;
				}
			}
			// surface unmapped mixology-range items (e.g. digweed-boosted
			// variants) so gaps in the id map show up in the log
			if (!known && itemId >= 29971 && itemId <= 30060 && itemId != 30031
				&& !warnedItemIds.contains(itemId))
			{
				warnedItemIds.add(itemId);
				log.debug("unmapped mixology-range item id {} in inventory", itemId);
			}
		}
		// station contents as (stationObjectId, potion) pairs so covering
		// an order also tells us WHICH station is working for it
		List<int[]> stationContents = new ArrayList<>();
		int[][] stationVarbits = {
			{VarbitID.MM_LAB_AGITATOR_POTION, MixologyObjects.STATION_AGITATOR},
			{VarbitID.MM_LAB_RETORT_POTION, MixologyObjects.STATION_RETORT},
			{VarbitID.MM_LAB_ALEMBIC_POTION, MixologyObjects.STATION_ALEMBIC},
		};
		for (int[] sv : stationVarbits)
		{
			MixPotion p = MixPotion.fromVarbit(client.getVarbitValue(sv[0]));
			if (p != null)
			{
				stationContents.add(new int[]{sv[1], p.ordinal()});
			}
		}
		MixPotion vessel = MixPotion.fromVarbit(vesselPotion);

		// cover MAKE orders in ranked sequence
		MixPotion mixTarget = null;
		int stationTarget = 0;
		int inProgressStation = 0;
		boolean vesselCollect = false;
		int makeCount = 0;
		int finishedCovered = 0;
		for (MixologyState.Order order : state.getOrders())
		{
			if (!order.isMake())
			{
				continue;
			}
			makeCount++;
			MixPotion p = order.getPotion();
			if (take(finished, p))
			{
				finishedCovered++;
				continue;
			}
			int stationId = takeStation(stationContents, p);
			if (stationId != 0)
			{
				if (inProgressStation == 0)
				{
					inProgressStation = stationId;
				}
				continue;
			}
			if (vessel == p)
			{
				vessel = null;
				vesselCollect = true;
				continue;
			}
			if (take(unfinished, p))
			{
				// THIS order's station, so a second identical potion is
				// guided to the second order's (possibly different) station
				if (stationTarget == 0)
				{
					stationTarget = MixologyObjects.stationForModifier(order.getModifier());
				}
				continue;
			}
			if (mixTarget == null)
			{
				mixTarget = p;
			}
		}
		state.setMixTarget(mixTarget);
		state.setStationTargetId(mixTarget == null ? stationTarget : 0);

		// single-action queue, in natural gameplay order
		MixologyState.LabAction action;
		int actionStation = 0;
		if (vesselCollect)
		{
			action = MixologyState.LabAction.COLLECT_VESSEL;
		}
		else if (mixTarget != null)
		{
			action = MixologyState.LabAction.MIX;
		}
		else if (stationTarget != 0)
		{
			action = MixologyState.LabAction.USE_STATION;
			actionStation = stationTarget;
		}
		else if (inProgressStation != 0)
		{
			action = MixologyState.LabAction.ATTEND_STATION;
			actionStation = inProgressStation;
		}
		else if (makeCount > 0 && finishedCovered == makeCount)
		{
			action = MixologyState.LabAction.DEPOSIT;
		}
		else
		{
			action = MixologyState.LabAction.NONE;
		}
		state.setLabAction(action);
		state.setActionStationId(actionStation);

		// remaining lever pulls = recipe minus current mixer slots
		int[] remaining = new int[3];
		if (mixTarget != null)
		{
			for (char c : mixTarget.getCode().toCharArray())
			{
				remaining[componentIndex(c)]++;
			}
			for (int varbit : new int[]{VarbitID.MM_LAB_MIXER_SLOT_0,
				VarbitID.MM_LAB_MIXER_SLOT_1, VarbitID.MM_LAB_MIXER_SLOT_2})
			{
				int v = client.getVarbitValue(varbit);
				if (v >= 1 && v <= 3 && remaining[v - 1] > 0)
				{
					remaining[v - 1]--;
				}
				else if (v > 3 && !warnedMixerValues)
				{
					warnedMixerValues = true;
					log.debug("unexpected mixer slot value {}, lever counts may ignore current slots", v);
				}
			}
		}
		state.setLeverRemaining(remaining);

		updateDigweed();

		// quick-action flash upkeep
		if (flashStationId != 0)
		{
			boolean agitator = flashStationId == MixologyObjects.STATION_AGITATOR;
			int progress = client.getVarbitValue(agitator
				? VarbitID.MM_AGITATOR_PROGRESS : VarbitID.MM_ALEMBIC_PROGRESS);
			int skillshot = client.getVarbitValue(agitator
				? VarbitID.MM_LAB_HIT_SKILLSHOT_AGITATOR : VarbitID.MM_LAB_HIT_SKILLSHOT_ALEMBIC);
			int potion = client.getVarbitValue(agitator
				? VarbitID.MM_LAB_AGITATOR_POTION : VarbitID.MM_LAB_ALEMBIC_POTION);
			if (skillshot != flashStartSkillshot || potion == 0
				|| progress > flashStartProgress + flashWindow
				|| progress < flashStartProgress)
			{
				flashStationId = 0;
			}
		}
		state.setQuickActionId(flashStationId);
	}

	private static int componentIndex(char c)
	{
		return c == 'M' ? 0 : c == 'A' ? 1 : 2;
	}

	/**
	 * Digweed attention: pickable spawns (world highlight + screen flash),
	 * the target order showing up while a digweed is held or already
	 * combined (screen flash), and the combine-now inventory flash.
	 */
	private void updateDigweed()
	{
		// A spot is pickable when its varbit is exactly 1 OR its multiloc
		// impostor is the mature plant (varbit 0 shows the non-pickable
		// young plant, 2 shows nothing; cache-verified). The union
		// tolerates a wrong varbit->corner mapping; log flags disagreement.
		List<Integer> readyHerbs = new ArrayList<>();
		for (int i = 0; i < MixologyObjects.HERB_SPOTS.length; i++)
		{
			int herbId = MixologyObjects.HERB_SPOTS[i];
			if (labObjects.get(herbId) == null)
			{
				continue;
			}
			boolean varbitReady = client.getVarbitValue(HERB_VARBITS[i]) == 1;
			boolean impostorReady = herbImpostorPickable(herbId);
			if (varbitReady || impostorReady)
			{
				readyHerbs.add(herbId);
			}
			if (varbitReady != impostorReady && !warnedHerbSignals)
			{
				warnedHerbSignals = true;
				log.debug("herb spot {} signals disagree: varbit={} impostor={}",
					herbId, varbitReady, impostorReady);
			}
		}
		state.setReadyHerbObjectIds(readyHerbs);
		boolean anyReady = !readyHerbs.isEmpty();
		if (anyReady && !wasHerbReady)
		{
			triggerScreenFlash("Digweed spawned, go pick it!", FLASH_DIGWEED);
		}
		wasHerbReady = anyReady;

		boolean digweedHeld = inventoryItems.contains(ItemID.MM_LAB_SPECIAL_HERB);
		state.setDigweedHeld(digweedHeld);
		MixPotion target = state.getDigweedTarget();
		state.setDigweedComboReady(digweedHeld && target != null
			&& (inventoryItems.contains(target.getUnfinishedItemId())
			|| inventoryItems.contains(target.getFinishedItemId())));

		if (!inLab())
		{
			digweedArmed = false; // digweed withers on leaving the lab
		}
		boolean attention = state.isDigweedTargetOrdered()
			&& (digweedHeld || digweedArmed) && target != null;
		if (attention && !wasTargetAttention)
		{
			triggerScreenFlash(target.getDisplayName() + " ordered, digweed time!", FLASH_ORDERED);
		}
		wasTargetAttention = attention;
	}

	private boolean herbImpostorPickable(int herbId)
	{
		ObjectComposition comp = client.getObjectDefinition(herbId);
		if (comp == null || comp.getImpostorIds() == null)
		{
			return false;
		}
		ObjectComposition impostor = comp.getImpostor();
		return impostor != null && impostor.getId() == MixologyObjects.HERB_MATURE;
	}

	private void triggerScreenFlash(String text, Color color)
	{
		if (!config.flashScreenDigweed() || !state.isInLab())
		{
			return;
		}
		state.setScreenFlashText(text);
		state.setScreenFlashColor(color);
		state.setScreenFlashUntilMs(System.currentTimeMillis() + 3200);
	}

	private boolean inLab()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return false;
		}
		WorldPoint location = local.getWorldLocation();
		return location.getPlane() == 0 && location.getRegionID() == LAB_REGION;
	}

	private void recompute(int[] signals)
	{
		// points changing while the digweed target was ordered = that
		// deposit presumably included the boosted potion, so stop watching
		boolean pointsChanged = state.getMox() != signals[6]
			|| state.getAga() != signals[7] || state.getLye() != signals[8];
		if (pointsChanged && state.isDigweedTargetOrdered())
		{
			digweedArmed = false;
		}

		state.setMox(signals[6]);
		state.setAga(signals[7]);
		state.setLye(signals[8]);

		if (state.getSessionStartBundles() < 0 && (signals[6] + signals[7] + signals[8]) > 0)
		{
			state.setSessionStartBundles(state.bundles());
			state.setSessionStartMs(System.currentTimeMillis());
		}
		if (signals[6] + signals[7] + signals[8] > 0)
		{
			state.recordBalanceSample();
		}

		// collect the current orders
		List<MixPotion> potions = new ArrayList<>();
		List<Integer> modifiers = new ArrayList<>();
		for (int i = 0; i < 3; i++)
		{
			MixPotion potion = MixPotion.fromVarbit(signals[i]);
			if (potion != null)
			{
				potions.add(potion);
				modifiers.add(signals[3 + i]);
			}
		}

		// Best deposit SET: fulfilling 2 orders in one deposit gives +20%
		// resin, all 3 gives +40%, so evaluate every subset with its
		// bonus, not potions individually.
		int n = potions.size();
		int bestMask = 0;
		double bestMetric = -1;
		double bestGain = 0;
		boolean perPotion = config.optimizeMode() == MixologyConfig.OptimizeMode.PER_POTION;
		for (int mask = 1; mask < (1 << n); mask++)
		{
			int count = Integer.bitCount(mask);
			double bonus = count == 3 ? 1.4 : count == 2 ? 1.2 : 1.0;
			int dm = 0;
			int da = 0;
			int dl = 0;
			for (int i = 0; i < n; i++)
			{
				if ((mask & (1 << i)) != 0)
				{
					dm += potions.get(i).getMoxPoints();
					da += potions.get(i).getAgaPoints();
					dl += potions.get(i).getLyePoints();
				}
			}
			double gain = state.bundlesFor(
				state.getMox() + (int) (dm * bonus),
				state.getAga() + (int) (da * bonus),
				state.getLye() + (int) (dl * bonus)) - state.bundles();
			// Time mode divides by potion count: boards reroll on any
			// deposit, so gain per potion of effort is what compounds.
			double metric = perPotion ? gain / count : gain;
			if (metric > bestMetric + 1e-12
				|| (Math.abs(metric - bestMetric) <= 1e-12 && bestMask != 0
				&& count < Integer.bitCount(bestMask)))
			{
				bestMetric = metric;
				bestGain = gain;
				bestMask = mask;
			}
		}

		List<MixologyState.Order> scored = new ArrayList<>();
		for (int i = 0; i < n; i++)
		{
			scored.add(new MixologyState.Order(potions.get(i), modifiers.get(i),
				state.marginalGain(potions.get(i), 1), 0,
				(bestMask & (1 << i)) != 0));
		}
		scored.sort(Comparator
			.comparing(MixologyState.Order::isMake).reversed()
			.thenComparing(Comparator.comparingDouble(MixologyState.Order::getScore).reversed()));
		List<MixologyState.Order> ranked = new ArrayList<>();
		for (int i = 0; i < scored.size(); i++)
		{
			MixologyState.Order o = scored.get(i);
			ranked.add(new MixologyState.Order(o.getPotion(), o.getModifier(), o.getScore(), i, o.isMake()));
		}
		state.setOrders(ranked);
		state.setBestSetSize(Integer.bitCount(bestMask));
		state.setBestSetGain(Math.max(0, bestGain));
		state.setBestSetBonusPct(Integer.bitCount(bestMask) == 3 ? 40
			: Integer.bitCount(bestMask) == 2 ? 20 : 0);
		state.setRerollAdvised(bestGain <= 1e-12 && !ranked.isEmpty());

		if (!ranked.isEmpty())
		{
			log.debug("mixology points: mox={} aga={} lye={} bundles={}",
				state.getMox(), state.getAga(), state.getLye(),
				String.format("%.3f", state.bundles()));
			for (MixologyState.Order o : ranked)
			{
				log.debug("mixology order rank {}: {} ({}) score={} [raw type varbits {},{},{}]",
					o.getRank(), o.getPotion().getDisplayName(),
					MixPotion.modifierName(o.getModifier()),
					String.format("%.4f", o.getScore()),
					signals[0], signals[1], signals[2]);
			}
		}

		// digweed: the potion whose DOUBLED reward adds the most on top of
		// its base reward (ties -> highest total, which favours Mixalot)
		MixPotion bestTarget = null;
		double bestValue = -1;
		for (MixPotion p : MixPotion.values())
		{
			double bonus = state.bundlesFor(
				state.getMox() + 2 * p.getMoxPoints(),
				state.getAga() + 2 * p.getAgaPoints(),
				state.getLye() + 2 * p.getLyePoints())
				- state.bundlesFor(
				state.getMox() + p.getMoxPoints(),
				state.getAga() + p.getAgaPoints(),
				state.getLye() + p.getLyePoints());
			int total = p.getMoxPoints() + p.getAgaPoints() + p.getLyePoints();
			if (bonus > bestValue + 1e-12
				|| (Math.abs(bonus - bestValue) <= 1e-12 && bestTarget != null
				&& total > bestTarget.getMoxPoints() + bestTarget.getAgaPoints() + bestTarget.getLyePoints()))
			{
				bestValue = bonus;
				bestTarget = p;
			}
		}
		state.setDigweedTarget(bestTarget);
		if (bestTarget != null && !ranked.isEmpty())
		{
			log.debug("mixology digweed target: {}", bestTarget.getDisplayName());
		}
		boolean ordered = false;
		for (MixologyState.Order o : ranked)
		{
			if (o.getPotion() == bestTarget)
			{
				ordered = true;
				break;
			}
		}
		state.setDigweedTargetOrdered(ordered);
	}

	private static BufferedImage createIcon()
	{
		BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = icon.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setColor(new Color(30, 70, 35));
		g.fillRoundRect(0, 0, 16, 16, 5, 5);
		g.setColor(new Color(120, 230, 120));
		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 8));
		g.drawString("MIX", 1, 11);
		g.dispose();
		return icon;
	}

	@Provides
	MixologyConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MixologyConfig.class);
	}
}

package com.liam.mixology;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Singleton;
import net.runelite.api.TileObject;
import net.runelite.api.gameval.ObjectID;

/**
 * Live references to the lab's interactive objects, tracked by spawn
 * events (the AGA lever is a decorative object, hence TileObject).
 */
@Singleton
public class MixologyObjects
{
	public static final int LEVER_MOX = ObjectID.MM_LAB_SWITCH_MOX;
	public static final int LEVER_AGA = ObjectID.MM_LAB_SWITCH_AGA;
	public static final int LEVER_LYE = ObjectID.MM_LAB_SWITCH_LYE;
	public static final int STATION_RETORT = ObjectID.MM_LAB_MACHINE_RETORT;
	public static final int STATION_AGITATOR = ObjectID.MM_LAB_MACHINE_AGITATOR;
	public static final int STATION_ALEMBIC = ObjectID.MM_LAB_MACHINE_ALEMBIC;
	public static final int VESSEL = ObjectID.MM_LAB_VESSEL;
	public static final int CONVEYOR = ObjectID.MM_LAB_CONVEYOR;
	// digweed spawn spots (multiloc parents, one per corner); their varbit
	// morphs them 0 -> "Young digweed" (always visible, not pickable),
	// 1 -> "Mature digweed" (pickable), 2 -> nothing (cache-verified)
	public static final int HERB_SPOT_1 = ObjectID.MM_HERB_1;
	public static final int HERB_SPOT_2 = ObjectID.MM_HERB_2;
	public static final int HERB_SPOT_3 = ObjectID.MM_HERB_3;
	public static final int HERB_SPOT_4 = ObjectID.MM_HERB_4;
	public static final int[] HERB_SPOTS = {HERB_SPOT_1, HERB_SPOT_2, HERB_SPOT_3, HERB_SPOT_4};
	public static final int HERB_MATURE = ObjectID.MM_HERB_READY;

	private final Map<Integer, TileObject> objects = new HashMap<>();

	public void track(TileObject object)
	{
		if (object == null)
		{
			return;
		}
		switch (object.getId())
		{
			case LEVER_MOX:
			case LEVER_AGA:
			case LEVER_LYE:
			case STATION_RETORT:
			case STATION_AGITATOR:
			case STATION_ALEMBIC:
			case VESSEL:
			case CONVEYOR:
			case HERB_SPOT_1:
			case HERB_SPOT_2:
			case HERB_SPOT_3:
			case HERB_SPOT_4:
				objects.put(object.getId(), object);
				break;
			default:
		}
	}

	public void untrack(TileObject object)
	{
		if (object != null)
		{
			objects.remove(object.getId(), object);
		}
	}

	public TileObject get(int objectId)
	{
		return objects.get(objectId);
	}

	public void clear()
	{
		objects.clear();
	}

	/**
	 * Station object id for an order modifier (1=Agitator, 2=Retort,
	 * 3=Alembic).
	 */
	public static int stationForModifier(int modifier)
	{
		switch (modifier)
		{
			case 1:
				return STATION_AGITATOR;
			case 2:
				return STATION_RETORT;
			case 3:
				return STATION_ALEMBIC;
			default:
				return 0;
		}
	}
}

package com.liam.mixology;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Flashes the digweed and its target potion in the inventory at the
 * combine-now moment: both are held together, ready to mix.
 */
@Singleton
public class DigweedFlashOverlay extends WidgetItemOverlay
{
	private static final int DIGWEED_ITEM_ID = ItemID.MM_LAB_SPECIAL_HERB;
	private static final long FLASH_PERIOD_MS = 700;

	private final MixologyState state;
	private final MixologyConfig config;

	@Inject
	private DigweedFlashOverlay(MixologyState state, MixologyConfig config)
	{
		this.state = state;
		this.config = config;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.flashDigweed() || !state.isInLab()
			|| state.getDigweedTarget() == null || !state.isDigweedComboReady())
		{
			return;
		}
		MixPotion target = state.getDigweedTarget();
		boolean isDigweed = itemId == DIGWEED_ITEM_ID;
		boolean isTargetPotion = itemId == target.getUnfinishedItemId()
			|| itemId == target.getFinishedItemId();
		if (!isDigweed && !isTargetPotion)
		{
			return;
		}

		boolean bright = (System.currentTimeMillis() / FLASH_PERIOD_MS) % 2 == 0;
		Color color = isDigweed
			? (bright ? new Color(255, 220, 60) : new Color(160, 130, 20))
			: (bright ? new Color(0, 220, 90) : new Color(0, 120, 50));
		Rectangle b = widgetItem.getCanvasBounds();
		graphics.setColor(color);
		graphics.drawRect(b.x, b.y, b.width, b.height);
		graphics.drawRect(b.x + 1, b.y + 1, b.width - 2, b.height - 2);
	}
}

