package com.liam.mixology;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Ranked current orders with recipe blobs (mox blue / aga green /
 * lye red), the best deposit set marked MAKE, digweed advice, and the
 * aldarium count. Custom-painted for per-component colours.
 */
@Singleton
public class MixologyOverlay extends Overlay
{
	private static final Color BG = new Color(20, 24, 20, 210);
	private static final Color TITLE = new Color(120, 220, 120);
	private static final Color MAKE = new Color(0, 220, 90);
	private static final Color SKIP = new Color(140, 140, 140);
	private static final Color DIGWEED = new Color(255, 220, 60);
	private static final Color TEXT = Color.WHITE;

	private static final Color MOX = new Color(90, 130, 255);
	private static final Color AGA = new Color(60, 200, 80);
	private static final Color LYE = new Color(235, 70, 70);

	private static final int WIDTH = 250;
	private static final int ROW_H = 16;
	private static final int PAD = 6;
	private static final int BLOB = 7;

	private final MixologyState state;
	private final MixologyConfig config;

	@Inject
	private MixologyOverlay(MixologyState state, MixologyConfig config)
	{
		this.state = state;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.showOverlay() || !state.isInLab() || state.getOrders().isEmpty())
		{
			return null;
		}
		double s = config.overlayScale() / 100.0;
		int width = (int) (WIDTH * s);
		int rowH = (int) (ROW_H * s);
		int pad = (int) (PAD * s);
		int blob = (int) (BLOB * s);

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setFont(g.getFont().deriveFont(Font.PLAIN, (float) (12 * s)));
		FontMetrics fm = g.getFontMetrics();

		int rows = 2 + state.getOrders().size()
			+ (state.getBestSetSize() > 1 || state.isRerollAdvised() ? 1 : 0)
			+ (state.getDigweedTarget() != null ? 1 : 0);
		int height = pad * 2 + rows * rowH;

		g.setColor(BG);
		g.fillRoundRect(0, 0, width, height, (int) (8 * s), (int) (8 * s));

		int y = pad + rowH - (int) (4 * s);

		g.setColor(TITLE);
		g.setFont(g.getFont().deriveFont(Font.BOLD));
		FontMetrics boldFm = g.getFontMetrics();
		g.drawString("Noot's Mixology", (width - boldFm.stringWidth("Noot's Mixology")) / 2, y);
		g.setFont(g.getFont().deriveFont(Font.PLAIN));
		y += rowH;

		for (MixologyState.Order order : state.getOrders())
		{
			Color nameColor = order.isMake() ? MAKE : SKIP;
			String prefix = order.isMake() ? "MAKE  " : "skip  ";
			String name = order.getPotion().getDisplayName()
				+ " · " + MixPotion.modifierName(order.getModifier());

			g.setColor(nameColor);
			g.drawString(prefix + name, pad, y);

			// recipe blobs, right-aligned before the score
			String score = String.format("+%.2f", order.getScore());
			int scoreW = fm.stringWidth(score);
			int blobsX = width - pad - scoreW - (int) (6 * s) - 3 * (blob + 2);
			String code = order.getPotion().getCode();
			for (int i = 0; i < code.length(); i++)
			{
				g.setColor(componentColor(code.charAt(i)));
				g.fillOval(blobsX + i * (blob + 2), y - blob + 1, blob, blob);
				g.setColor(Color.BLACK);
				g.drawOval(blobsX + i * (blob + 2), y - blob + 1, blob, blob);
			}
			g.setColor(order.isMake() ? TEXT : SKIP);
			g.drawString(score, width - pad - scoreW, y);
			y += rowH;
		}

		if (state.isRerollAdvised())
		{
			g.setColor(SKIP);
			g.drawString("No progress here, deposit 1 to reroll the board", pad, y);
			y += rowH;
		}
		else if (state.getBestSetSize() > 1)
		{
			g.setColor(MAKE);
			g.drawString(String.format("Deposit %d together for +%d%% bonus",
				state.getBestSetSize(), state.getBestSetBonusPct()), pad, y);
			y += rowH;
		}

		if (state.getDigweedTarget() != null)
		{
			g.setColor(DIGWEED);
			g.drawString("Digweed: " + state.getDigweedTarget().getDisplayName()
				+ (state.isDigweedTargetOrdered() ? "  (ORDERED!)" : ""), pad, y);
			y += rowH;
		}

		g.setColor(TEXT);
		String reward = String.format("%s: %d (%.2f) · balance %.1f%%",
			state.getTargetReward().getShortName(),
			state.buyableNow(), state.bundles(), state.balancePercent());
		g.drawString(reward, pad, y);

		return new Dimension(width, height);
	}

	private static Color componentColor(char c)
	{
		switch (c)
		{
			case 'M':
				return MOX;
			case 'A':
				return AGA;
			case 'L':
				return LYE;
			default:
				return Color.GRAY;
		}
	}

}

package com.liam.mixology;

import java.util.ArrayList;
import java.util.List;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.Setter;
import lombok.Value;

/**
 * Current mixology situation + the bundle math. A "bundle" is one unit of
 * the selected target reward (e.g. aldarium at 80 mox / 60 aga / 90 lye);
 * effective wealth is the minimum of the per-resin ratios, so scoring a
 * potion = how much it raises that minimum. Mutated on the client thread;
 * panel reads snapshots.
 */
@Singleton
@Getter
@Setter
public class MixologyState
{
	private MixologyReward targetReward = MixologyReward.ALDARIUM;

	@Value
	public static class Order
	{
		MixPotion potion;
		int modifier;
		double score;
		int rank;
		/**
		 * True if this order is part of the best deposit set.
		 */
		boolean make;
	}

	private int mox;
	private int aga;
	private int lye;

	private List<Order> orders = new ArrayList<>();
	private MixPotion digweedTarget;
	private boolean digweedTargetOrdered;

	/**
	 * The best deposit set: how many potions, its total bundle gain, and
	 * the multi-order bonus percent it earns (0/20/40).
	 */
	private int bestSetSize;
	private double bestSetGain;
	private int bestSetBonusPct;

	/**
	 * True when nothing on this board helps the binding resin: the MAKE
	 * mark is only there to reroll the board.
	 */
	private boolean rerollAdvised;

	/**
	 * The local player is inside the lab region; set each tick.
	 */
	private boolean inLab;

	// ---- lab guidance (computed each tick on the client thread) ----

	/**
	 * The single current action, in natural gameplay order.
	 */
	public enum LabAction
	{
		NONE, COLLECT_VESSEL, MIX, USE_STATION, ATTEND_STATION, DEPOSIT
	}

	private LabAction labAction = LabAction.NONE;

	/**
	 * The station object id for USE_STATION / ATTEND_STATION actions.
	 */
	private int actionStationId;

	/**
	 * The next potion to mix at the levers, or null when nothing to mix.
	 */
	private MixPotion mixTarget;

	/**
	 * Remaining lever pulls for the mix target: [mox, aga, lye].
	 */
	private int[] leverRemaining = new int[3];

	/**
	 * Station object id to use next (0 = none).
	 */
	private int stationTargetId;

	/**
	 * Station object id currently flashing its quick-action window
	 * (0 = none).
	 */
	private int quickActionId;

	/**
	 * The mixing vessel holds a finished mix ready to collect.
	 */
	private boolean vesselReady;

	// ---- digweed attention (client thread only) ----

	/**
	 * Herb spot object ids with a pickable digweed right now.
	 */
	private List<Integer> readyHerbObjectIds = new ArrayList<>();

	/**
	 * A digweed is in the inventory.
	 */
	private boolean digweedHeld;

	/**
	 * Digweed AND its target potion are both in the inventory, ready to
	 * combine right now.
	 */
	private boolean digweedComboReady;

	/**
	 * Full-screen attention flash: active while now < untilMs.
	 */
	private long screenFlashUntilMs;
	private String screenFlashText = "";
	private java.awt.Color screenFlashColor = java.awt.Color.YELLOW;

	// session rate tracking for the ETA
	private double sessionStartBundles = -1;
	private long sessionStartMs;

	/**
	 * Session samples of (epochMs, balancePercent) for the ratio graph.
	 * Written on the client thread, read from the EDT.
	 */
	private final List<double[]> balanceSamples = new ArrayList<>();
	private int lastSampledMox = -1;
	private int lastSampledAga = -1;
	private int lastSampledLye = -1;

	/**
	 * Switching rewards rescales every ratio, so session rate tracking and
	 * the balance graph restart from the new baseline.
	 */
	public void setTargetReward(MixologyReward reward)
	{
		if (reward == null || reward == targetReward)
		{
			return;
		}
		targetReward = reward;
		sessionStartBundles = -1;
		sessionStartMs = 0;
		synchronized (this)
		{
			balanceSamples.clear();
			lastSampledMox = -1;
			lastSampledAga = -1;
			lastSampledLye = -1;
		}
	}

	/**
	 * Ratio balance: min/max of the cost-normalized resin ratios. 100% =
	 * points exactly proportional to the target reward's cost.
	 */
	public double balancePercent()
	{
		double rm = mox / (double) targetReward.getMoxCost();
		double ra = aga / (double) targetReward.getAgaCost();
		double rl = lye / (double) targetReward.getLyeCost();
		double max = Math.max(rm, Math.max(ra, rl));
		if (max <= 0)
		{
			return 0;
		}
		return 100.0 * Math.min(rm, Math.min(ra, rl)) / max;
	}

	public synchronized void recordBalanceSample()
	{
		if (mox == lastSampledMox && aga == lastSampledAga && lye == lastSampledLye)
		{
			return;
		}
		lastSampledMox = mox;
		lastSampledAga = aga;
		lastSampledLye = lye;
		balanceSamples.add(new double[]{System.currentTimeMillis(), balancePercent()});
		if (balanceSamples.size() > 2000)
		{
			balanceSamples.remove(0);
		}
	}

	public synchronized List<double[]> balanceSamplesCopy()
	{
		return new ArrayList<>(balanceSamples);
	}

	public double bundles()
	{
		return bundlesFor(mox, aga, lye);
	}

	public double bundlesFor(int mox, int aga, int lye)
	{
		return Math.min(mox / (double) targetReward.getMoxCost(),
			Math.min(aga / (double) targetReward.getAgaCost(),
				lye / (double) targetReward.getLyeCost()));
	}

	public int buyableNow()
	{
		return (int) Math.floor(bundles());
	}

	/**
	 * Marginal bundle gain from receiving this potion's points
	 * ({@code times} = 1 normally, 2 for digweed-boosted).
	 */
	public double marginalGain(MixPotion p, int times)
	{
		return bundlesFor(mox + times * p.getMoxPoints(),
			aga + times * p.getAgaPoints(),
			lye + times * p.getLyePoints()) - bundles();
	}
}

