/**
 * Goal tracker: resin balances, buyable aldarium, goal progress bar,
 * session ETA, and the ratio-balance graph.
 */
@Singleton
public class MixologyPanel extends PluginPanel
{
	private static final Color MOX = new Color(90, 130, 255);
	private static final Color AGA = new Color(60, 200, 80);
	private static final Color LYE = new Color(235, 70, 70);
	private static final Color ACCENT = new Color(120, 220, 120);

	private final MixologyState state;
	private final MixologyConfig config;
	private final ConfigManager configManager;

	private final JLabel moxLabel = stat("0", MOX);
	private final JLabel agaLabel = stat("0", AGA);
	private final JLabel lyeLabel = stat("0", LYE);
	private final JLabel buyableBig = new JLabel("0", SwingConstants.CENTER);
	private final JLabel buyableSub = new JLabel("", SwingConstants.CENTER);
	private final JSpinner goalSpinner = new JSpinner(new SpinnerNumberModel(100, 1, 10000, 1));
	private final JProgressBar progressBar = new JProgressBar();
	private final JLabel etaLabel = new JLabel();
	private final JLabel balanceLabel = new JLabel();
	private final BalanceGraph balanceGraph = new BalanceGraph();
	private final Timer refreshTimer;

	private static JLabel stat(String text, Color color)
	{
		JLabel l = new JLabel(text, SwingConstants.CENTER);
		l.setForeground(color);
		l.setFont(l.getFont().deriveFont(Font.BOLD, 13f));
		return l;
	}

	private static JPanel card(Component inner)
	{
		JPanel card = new JPanel(new BorderLayout());
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		card.add(inner, BorderLayout.CENTER);
		card.setAlignmentX(LEFT_ALIGNMENT);
		return card;
	}

	@Inject
	private MixologyPanel(MixologyState state, MixologyConfig config, ConfigManager configManager)
	{
		super(false);
		this.state = state;
		this.config = config;
		this.configManager = configManager;
		buyableSub.setText(config.targetReward().getDisplayName().toLowerCase() + " buyable");

		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel title = new JLabel("Noot's Mixology", SwingConstants.CENTER);
		title.setFont(title.getFont().deriveFont(Font.BOLD, 15f));
		title.setForeground(ACCENT);
		title.setAlignmentX(LEFT_ALIGNMENT);
		JPanel titleWrap = new JPanel(new BorderLayout());
		titleWrap.setBackground(ColorScheme.DARK_GRAY_COLOR);
		titleWrap.add(title, BorderLayout.CENTER);
		titleWrap.setAlignmentX(LEFT_ALIGNMENT);
		titleWrap.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		content.add(titleWrap);
		content.add(Box.createVerticalStrut(8));

		// resin balances with coloured headers
		JPanel resins = new JPanel(new GridLayout(2, 3, 4, 2));
		resins.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		resins.add(header("Mox", MOX));
		resins.add(header("Aga", AGA));
		resins.add(header("Lye", LYE));
		resins.add(moxLabel);
		resins.add(agaLabel);
		resins.add(lyeLabel);
		content.add(card(resins));
		content.add(Box.createVerticalStrut(8));

		// big buyable number
		buyableBig.setFont(buyableBig.getFont().deriveFont(Font.BOLD, 28f));
		buyableBig.setForeground(Color.WHITE);
		buyableSub.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		JPanel buyable = new JPanel();
		buyable.setLayout(new BoxLayout(buyable, BoxLayout.Y_AXIS));
		buyable.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		buyableBig.setAlignmentX(CENTER_ALIGNMENT);
		buyableSub.setAlignmentX(CENTER_ALIGNMENT);
		buyable.add(buyableBig);
		buyable.add(buyableSub);
		content.add(card(buyable));
		content.add(Box.createVerticalStrut(8));

		// goal + progress
		JPanel goal = new JPanel();
		goal.setLayout(new BoxLayout(goal, BoxLayout.Y_AXIS));
		goal.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		JPanel goalRow = new JPanel(new BorderLayout(6, 0));
		goalRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		JLabel goalLabel = new JLabel("Goal:");
		goalLabel.setForeground(Color.WHITE);
		goalRow.add(goalLabel, BorderLayout.WEST);
		goalRow.add(goalSpinner, BorderLayout.CENTER);
		goalRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		goalRow.setAlignmentX(LEFT_ALIGNMENT);
		goal.add(goalRow);
		goal.add(Box.createVerticalStrut(6));
		progressBar.setStringPainted(true);
		progressBar.setForeground(ACCENT);
		progressBar.setBackground(ColorScheme.DARK_GRAY_COLOR);
		progressBar.setAlignmentX(LEFT_ALIGNMENT);
		progressBar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));
		goal.add(progressBar);
		goal.add(Box.createVerticalStrut(6));
		etaLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		etaLabel.setAlignmentX(LEFT_ALIGNMENT);
		goal.add(etaLabel);
		content.add(card(goal));
		content.add(Box.createVerticalStrut(8));

		// ratio balance + graph
		JPanel balance = new JPanel();
		balance.setLayout(new BoxLayout(balance, BoxLayout.Y_AXIS));
		balance.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		balanceLabel.setAlignmentX(LEFT_ALIGNMENT);
		balance.add(balanceLabel);
		balance.add(Box.createVerticalStrut(6));
		balanceGraph.setAlignmentX(LEFT_ALIGNMENT);
		balance.add(balanceGraph);
		content.add(card(balance));

		add(content, BorderLayout.NORTH);

		goalSpinner.setValue(config.goalAldarium());
		goalSpinner.addChangeListener(e -> configManager.setConfiguration(
			MixologyConfig.GROUP, "goalAldarium", (int) goalSpinner.getValue()));

		refreshTimer = new Timer(5_000, e ->
		{
			if (isShowing())
			{
				refresh();
			}
		});
		refreshTimer.setRepeats(true);
	}

	private static JLabel header(String text, Color color)
	{
		JLabel l = new JLabel(text, SwingConstants.CENTER);
		l.setForeground(color.darker());
		l.setFont(l.getFont().deriveFont(Font.PLAIN, 11f));
		return l;
	}

	void startAutoRefresh()
	{
		SwingUtilities.invokeLater(() ->
		{
			refreshTimer.start();
			refresh();
		});
	}

	void stopAutoRefresh()
	{
		SwingUtilities.invokeLater(refreshTimer::stop);
	}

	public void refresh()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::refresh);
			return;
		}

		moxLabel.setText(String.format("%,d", state.getMox()));
		agaLabel.setText(String.format("%,d", state.getAga()));
		lyeLabel.setText(String.format("%,d", state.getLye()));

		double bundles = state.bundles();
		buyableBig.setText(String.valueOf(state.buyableNow()));
		buyableSub.setText(String.format("%s buyable (%.2f)",
			state.getTargetReward().getDisplayName().toLowerCase(), bundles));

		int goal = config.goalAldarium();
		progressBar.setMaximum(goal * 100);
		progressBar.setValue((int) Math.min(goal * 100, bundles * 100));
		progressBar.setString(String.format("%.1f%% of %d", 100.0 * bundles / Math.max(1, goal), goal));

		etaLabel.setText("<html>ETA: " + eta(goal, bundles) + "</html>");

		balanceLabel.setText(String.format(
			"<html>Ratio balance <b>%.2f%%</b>%s<br><small><font color='#9e9e9e'>100%% = points match the reward's cost ratio</font></small></html>",
			state.balancePercent(), balanceRate()));
		balanceGraph.repaint();
	}

	private String eta(int goal, double bundles)
	{
		if (bundles >= goal)
		{
			return "<b>done, go shopping!</b>";
		}
		double start = state.getSessionStartBundles();
		long startMs = state.getSessionStartMs();
		if (start < 0 || startMs == 0)
		{
			return "waiting for data...";
		}
		double elapsedHours = (System.currentTimeMillis() - startMs) / 3_600_000.0;
		double gained = bundles - start;
		if (elapsedHours < 0.05 || gained <= 0)
		{
			return "measuring your rate...";
		}
		double rate = gained / elapsedHours;
		double hoursLeft = (goal - bundles) / rate;
		long mins = Math.round(hoursLeft * 60);
		return String.format("<b>%dh %02dm</b> at %.1f/hr", mins / 60, mins % 60, rate);
	}

	private String balanceRate()
	{
		java.util.List<double[]> samples = state.balanceSamplesCopy();
		if (samples.size() < 2)
		{
			return "";
		}
		double[] first = samples.get(0);
		double[] last = samples.get(samples.size() - 1);
		double hours = (last[0] - first[0]) / 3_600_000.0;
		if (hours < 0.03)
		{
			return "";
		}
		double perHour = (last[1] - first[1]) / hours;
		return String.format(" <font color='%s'>%+.2f%%/hr</font>",
			perHour >= 0 ? "#00dc5a" : "#f44336", perHour);
	}

	/**
	 * Session sparkline of the ratio balance percent.
	 */
	private class BalanceGraph extends JPanel
	{
		BalanceGraph()
		{
			setPreferredSize(new Dimension(190, 80));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 80));
			setOpaque(true);
			setBackground(ColorScheme.DARK_GRAY_COLOR);
		}

		@Override
		protected void paintComponent(Graphics g0)
		{
			super.paintComponent(g0);
			Graphics2D g = (Graphics2D) g0;
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			java.util.List<double[]> samples = state.balanceSamplesCopy();
			int w = getWidth();
			int h = getHeight();
			if (samples.size() < 2)
			{
				g.setColor(Color.GRAY);
				g.drawString("collecting data...", 8, h / 2);
				return;
			}
			double t0 = samples.get(0)[0];
			double t1 = samples.get(samples.size() - 1)[0];
			double lo = Double.MAX_VALUE;
			double hi = -Double.MAX_VALUE;
			for (double[] s : samples)
			{
				lo = Math.min(lo, s[1]);
				hi = Math.max(hi, s[1]);
			}
			double pad = Math.max((hi - lo) * 0.1, 0.05);
			lo = Math.max(0, lo - pad);
			hi = Math.min(100, hi + pad);

			g.setColor(ACCENT);
			int px = -1;
			int py = -1;
			for (double[] s : samples)
			{
				int x = (int) ((s[0] - t0) / Math.max(1, t1 - t0) * (w - 10)) + 5;
				int y = h - 5 - (int) ((s[1] - lo) / Math.max(1e-9, hi - lo) * (h - 10));
				if (px >= 0)
				{
					g.drawLine(px, py, x, y);
				}
				px = x;
				py = y;
			}
			g.setColor(Color.GRAY);
			g.setFont(g.getFont().deriveFont(10f));
			g.drawString(String.format("%.2f%%", hi), 4, 12);
			g.drawString(String.format("%.2f%%", lo), 4, h - 4);
		}
	}
}

package com.liam.mixology;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Short full-screen attention flash: a pulsing tint with a steady message,
 * used for digweed spawns and the digweed target order appearing.
 */
@Singleton
public class MixologyScreenFlashOverlay extends Overlay
{
	private static final long PULSE_MS = 300;
	private static final int TINT_ALPHA = 50;

	private final Client client;
	private final MixologyState state;
	private final MixologyConfig config;

	@Inject
	private MixologyScreenFlashOverlay(Client client, MixologyState state, MixologyConfig config)
	{
		this.client = client;
		this.state = state;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		long now = System.currentTimeMillis();
		if (!state.isInLab() || now >= state.getScreenFlashUntilMs())
		{
			return null;
		}
		Color color = state.getScreenFlashColor();
		if ((now / PULSE_MS) % 2 == 0)
		{
			graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), TINT_ALPHA));
			graphics.fillRect(0, 0, client.getCanvasWidth(), client.getCanvasHeight());
		}
		String text = state.getScreenFlashText();
		if (text != null && !text.isEmpty())
		{
			float size = 26f * config.overlayScale() / 100f;
			graphics.setFont(graphics.getFont().deriveFont(Font.BOLD, size));
			FontMetrics fm = graphics.getFontMetrics();
			int x = (client.getCanvasWidth() - fm.stringWidth(text)) / 2;
			int y = client.getCanvasHeight() / 4;
			graphics.setColor(Color.BLACK);
			graphics.drawString(text, x + 2, y + 2);
			graphics.setColor(color);
			graphics.drawString(text, x, y);
		}
		return null;
	}
}
